// Complete and display the user-selected R&E logo.
(() => {
  const source = "data:image/png;base64," + window.__reLogoSelected.concat([
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    ""
  ]).join("");
  delete window.__reLogoSelected;
  document.querySelectorAll("img[data-re-logo]").forEach((image) => { image.src = source; });
  document.querySelector('link[rel="icon"]').href = source;
})();
